insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select id,'BUTTON','GamePositionList','查询游戏位置','business:game-position:list',6 from sys_menu where name='Game' and not exists(select 1 from sys_menu where auth_mark='business:game-position:list');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select id,'BUTTON','GamePositionCreate','新增游戏位置','business:game-position:create',7 from sys_menu where name='Game' and not exists(select 1 from sys_menu where auth_mark='business:game-position:create');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select id,'BUTTON','GamePositionUpdate','编辑游戏位置','business:game-position:update',8 from sys_menu where name='Game' and not exists(select 1 from sys_menu where auth_mark='business:game-position:update');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select id,'BUTTON','GamePositionDelete','删除游戏位置','business:game-position:delete',9 from sys_menu where name='Game' and not exists(select 1 from sys_menu where auth_mark='business:game-position:delete');
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='admin' and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
